item.aggregated_output:
  1	import {createHash} from "node:crypto";
  2	
  3	import Decimal from "decimal.js";
  4	import {z} from "zod";
  5	
  6	/**
  7	 * Executor of the method `build-debt-ledger`, tenth version after nine independent reviews.
  8	 * Deterministic: the same rows, the same numbers, whatever their order; duplicate ids are refused.
  9	 * Every row carries the anchor of its balance and, field by field, the anchor of each term it
 10	 * states; the two facts of a lender (formal holder, economic creditors) each carry their own anchor.
 11	 * A contra line is not an obligation. A net debt view is computed only when its definition is in the
 12	 * base and its text agrees with the formula executed. Reconciliation runs on the total and, when the
 13	 * rows carry the split, on current and non-current separately; the first period of the schedule is
 14	 * checked against the current liabilities. A tolerance above zero needs a versioned policy. An
 15	 * empty ledger exists only on evidence, and silence blocks. Every calculation lists its operands.
 16	 * The first period of the schedule is the one that ends within twelve months of the reference date,
 17	 * never a label; each row's split must add up to its balance; a definition's text is parsed into what
 18	 * it adds and what it deducts before the formula runs; fingerprints ignore key and nested-array order.
 19	 */
 20	const money = z.string().regex(/^-?\d+(\.\d+)?$/);
 21	const nonNegativeMoney = z.string().regex(/^\d+(\.\d+)?$/);
 22	/** A calendar date that exists: 2026-02-30 is refused, not silently rolled over. */
 23	const calendarDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine((value) => { const date = new Date(`${value}T00:00:00Z`); return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value; }, {message: "not a calendar date"});
 24	const nonEmpty = z.string().trim().min(1);
 25	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional(), table: nonEmpty.optional()}).strict();
 26	type Anchor = z.infer<typeof anchorSchema>;
 27	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 28	
 29	export const remunerationSchema = z.discriminatedUnion("type", [
 30	  z.object({type: z.literal("spread_over_index"), index: z.enum(["CDI", "IPCA", "SOFR", "other"]), spreadPercentPerYear: z.string().regex(/^-?\d+(\.\d+)?$/)}).strict(),
 31	  z.object({type: z.literal("percent_of_index"), index: z.enum(["CDI", "SOFR", "other"]), percentOfIndex: nonNegativeMoney}).strict(),
 32	  z.object({type: z.literal("fixed"), ratePercentPerYear: z.string().regex(/^-?\d+(\.\d+)?$/)}).strict(),
 33	]);
 34	
 35	export const debtLedgerRowInputSchema = z.object({
 36	  id: nonEmpty,
 37	  instrument: nonEmpty,
 38	  series: nonEmpty.optional(),
 39	  /** Absent on contra lines, which are not obligations to a lender. */
 40	  obligation: z.object({
 41	    kind: z.enum(["loan", "debenture", "commercial_note", "cpr", "lease", "other"]),
 42	    /** Only disbursed obligations are debt; an authorized operation is not a row. */
 43	    disbursed: z.literal(true),
 44	    /** The views this row belongs to, as the definitions state; a lease inside the contractual view needs the anchor of that inclusion. */
 45	    views: z.array(z.enum(["release", "contractual"])).min(1),
 46	  }).strict().optional(),
 47	  balance: money,
 48	  priorBalance: money.nullable().default(null),
 49	  currency: z.string().regex(/^[A-Z]{3}$/),
 50	  remuneration: remunerationSchema.nullable().default(null),
 51	  maturity: calendarDate.nullable().default(null),
 52	  guarantee: nonEmpty.nullable().default(null),
 53	  lender: z.object({formalHolder: nonEmpty.nullable(), economicCreditors: nonEmpty.nullable()}).strict().nullable().default(null),
 54	  /** Current and non-current parts; non-negative on obligations, non-positive on contra lines, and adding up to the balance either way. */
 55	  classification: z.object({current: money, nonCurrent: money}).strict().nullable().default(null),
 56	  /** Transaction costs and similar contra lines are part of the note's total but are not debt to a lender; they must be negative. */
 57	  contra: z.boolean().default(false),
 58	  anchors: z.object({
 59	    balance: anchorSchema,
 60	    remuneration: anchorSchema.optional(),
 61	    maturity: anchorSchema.optional(),
 62	    guarantee: anchorSchema.optional(),
 63	    lenderFormalHolder: anchorSchema.optional(),
 64	    lenderEconomicCreditors: anchorSchema.optional(),
 65	    classification: anchorSchema.optional(),
 66	    /** Where the base says this row belongs to the contractual view (needed for leases). */
 67	    viewInclusion: anchorSchema.optional(),
 68	  }).strict(),
 69	}).strict().superRefine((row, context) => {
 70	  const balance = new Decimal(row.balance);
 71	  if (row.contra && balance.gte(0)) context.addIssue({code: "custom", path: ["contra"], message: `contra line ${row.id} must carry a negative balance`});
 72	  if (row.priorBalance !== null && row.contra && new Decimal(row.priorBalance).gt(0)) context.addIssue({code: "custom", path: ["priorBalance"], message: `contra line ${row.id} cannot carry a positive prior balance`});
 73	  if (row.priorBalance !== null && !row.contra && new Decimal(row.priorBalance).lt(0)) context.addIssue({code: "custom", path: ["priorBalance"], message: `row ${row.id} has a negative prior balance and is not a contra line`});
 74	  if (!row.contra && balance.lt(0)) context.addIssue({code: "custom", path: ["balance"], message: `row ${row.id} has a negative balance and is not a contra line`});
 75	  if (row.contra && row.obligation) context.addIssue({code: "custom", path: ["obligation"], message: `contra line ${row.id} is not an obligation to a lender; drop its obligation`});
 76	  if (!row.contra && !row.obligation) context.addIssue({code: "custom", path: ["obligation"], message: `row ${row.id} needs its obligation (kind, disbursed, views)`});
 77	  for (const field of ["remuneration", "maturity", "guarantee", "classification"] as const) {
 78	    if (row[field] !== null && row[field] !== undefined && !row.anchors[field]) context.addIssue({code: "custom", path: ["anchors", field], message: `${field} of ${row.id} is stated without an anchor; a term without a source is not a term`});
 79	  }
 80	  if (row.lender?.formalHolder && !row.anchors.lenderFormalHolder) context.addIssue({code: "custom", path: ["anchors", "lenderFormalHolder"], message: `the formal holder of ${row.id} is stated without an anchor`});
 81	  if (row.lender?.economicCreditors && !row.anchors.lenderEconomicCreditors) context.addIssue({code: "custom", path: ["anchors", "lenderEconomicCreditors"], message: `the economic creditors of ${row.id} are stated without an anchor`});
 82	  if (row.obligation && !row.obligation.views.includes("release") && !row.anchors.viewInclusion) context.addIssue({code: "custom", path: ["anchors", "viewInclusion"], message: `${row.id} sits only in the contractual view without the anchor that includes it`});
 83	  if (row.classification && !new Decimal(row.classification.current).plus(row.classification.nonCurrent).eq(balance)) context.addIssue({code: "custom", path: ["classification"], message: `the split of ${row.id} (${row.classification.current} + ${row.classification.nonCurrent}) does not add up to its balance ${row.balance}`});
 84	  if (row.classification && !row.contra && (new Decimal(row.classification.current).lt(0) || new Decimal(row.classification.nonCurrent).lt(0))) context.addIssue({code: "custom", path: ["classification"], message: `the split of ${row.id} has a negative part on an obligation`});
 85	  if (row.classification && row.contra && (new Decimal(row.classification.current).gt(0) || new Decimal(row.classification.nonCurrent).gt(0))) context.addIssue({code: "custom", path: ["classification"], message: `the split of contra line ${row.id} has a positive part`});
 86	});
 87	
 88	export const toleranceSchema = z.object({
 89	  value: nonNegativeMoney,
 90	  /** A tolerance above zero exists only under a versioned policy. */
 91	  policyKey: nonEmpty.optional(),
 92	  policyVersion: nonEmpty.optional(),
 93	}).strict().superRefine((tolerance, context) => {
 94	  if (!new Decimal(tolerance.value).isZero() && (!tolerance.policyKey || !tolerance.policyVersion)) context.addIssue({code: "custom", path: ["policyKey"], message: "a tolerance above zero needs policyKey and policyVersion"});
 95	});
 96	
 97	export const debtLedgerInputSchema = z.object({
 98	  referenceDate: calendarDate,
 99	  priorDate: calendarDate.nullable().default(null),
100	  unit: z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]),
101	  /** Where the statements declare the unit ("em milhares de reais"); a unit without its declaration is a label. */
102	  unitAnchor: anchorSchema,
103	  /** `note` when the debt note of the statements is in the base; `release_only` blocks: a release is not a ledger. */
104	  source: z.enum(["note", "release_only"]),
105	  rows: z.array(debtLedgerRowInputSchema),
106	  /** Present when the base proves the company has no onerous debt; the ledger is then empty on evidence, not on silence. */
107	  noDebtEvidence: anchorSchema.optional(),
108	  /** Independent totals from the balance sheet itself, never from the debt note. */
109	  balanceSheet: z.object({current: money, nonCurrent: money, anchor: anchorSchema}).strict().optional(),
110	  schedule: z.object({
111	    /** `endsAt` is the calendar end of the period; null for open-ended buckets and adjustment lines. */
112	    periods: z.array(z.object({period: nonEmpty, amount: money, endsAt: calendarDate.nullable()}).strict()).min(1),
113	    anchor: anchorSchema,
114	  }).strict().optional(),
115	  /** Each component may be absent from the base; a view that needs it is then not computed, with the gap named. */
116	  cash: z.object({
117	    cashAndEquivalents: z.object({value: money, anchor: anchorSchema}).strict().nullable(),
118	    financialInvestments: z.object({value: money, anchor: anchorSchema}).strict().nullable(),
119	    derivativeAssets: z.object({value: money, anchor: anchorSchema}).strict().nullable(),
120	    derivativeLiabilities: z.object({value: money, anchor: anchorSchema}).strict().nullable(),
121	  }).strict().optional(),
122	  /** The literal definitions with their sources; a view is computed only when its definition is here and agrees with the formula. */
123	  definitions: z.object({
124	    release: z.object({text: nonEmpty, anchor: anchorSchema}).strict().optional(),
125	    contractual: z.object({text: nonEmpty, anchor: anchorSchema}).strict().optional(),
126	  }).strict().default({}),
127	  releaseReportedNetDebt: z.object({value: money, anchor: anchorSchema}).strict().optional(),
128	  tolerance: toleranceSchema.default({value: "0"}),
129	}).strict().superRefine((input, context) => {
130	  const ids = new Set<string>();
131	  for (const row of input.rows) {
132	    if (ids.has(row.id)) context.addIssue({code: "custom", path: ["rows"], message: `duplicate row id ${row.id}`});
133	    ids.add(row.id);
134	  }
135	  const periods = new Set<string>();
136	  for (const period of input.schedule?.periods ?? []) {
137	    if (periods.has(period.period)) context.addIssue({code: "custom", path: ["schedule", "periods"], message: `duplicate period ${period.period}`});
138	    periods.add(period.period);
139	  }
140	});
141	export type DebtLedgerInput = z.input<typeof debtLedgerInputSchema>;
142	
143	type Row = z.infer<typeof debtLedgerRowInputSchema>;
144	type View = {value: string; definition: string; definitionSource: Anchor; components: Record<string, string>; componentAnchors: Record<string, Anchor>; rowsIncluded: string[]; residualAssumedZero: boolean};
145	type UncoveredField = "remuneration" | "maturity" | "guarantee" | "lender_formal_holder" | "lender_economic_creditors" | "classification";
146	
147	export type DebtLedgerOutput = {
148	  schema_version: "method.build-debt-ledger.v10";
149	  reference_date: string;
150	  prior_date: string | null;
151	  unit: string;
152	  unit_anchor: Anchor;
153	  source: "note" | "release_only";
154	  state: "complete" | "blocked" | "empty" | "incomplete";
155	  block_reasons: string[];
156	  incomplete_reasons: string[];
157	  ledger_rows: Array<{
158	    id: string; instrument: string; series: string | null; obligation: Row["obligation"] | null; balance: string; priorBalance: string | null; currency: string;
159	    remuneration: Row["remuneration"]; maturity: string | null; guarantee: string | null; lender: Row["lender"]; classification: Row["classification"]; contra: boolean;
160	    anchors: Row["anchors"];
161	  }>;
162	  /** Sum of every row, including rows that only the contractual view carries (leases included by an indenture). */
163	  gross_debt: string;
164	  /** Sum of the rows the statements report as debt (release view and contra lines); this is what reconciles with the balance sheet. */
165	  gross_debt_reported: string;
166	  gross_debt_prior: string | null;
167	  gross_debt_before_contra: string;
168	  contractual_only_inclusions: Array<{rowId: string; balance: string; anchor: Anchor}>;
169	  reconciliation: {
170	    total: {state: "reconciled" | "difference" | "not_possible"; balanceSheetTotal: string | null; difference: string | null};
171	    split: {state: "reconciled" | "difference" | "not_possible"; currentDifference: string | null; nonCurrentDifference: string | null; reason: string | null};
172	    tolerance: {value: string; policyKey: string | null; policyVersion: string | null};
173	    anchor: Anchor | null;
174	  };
175	  schedule: {periods: Array<{period: string; amount: string; endsAt: string | null; shareOfGross: string}>; total: string; matchesGross: boolean; currentPeriod: {period: string; amount: string; balanceSheetCurrent: string; difference: string; matches: boolean} | null; anchor: Anchor} | null;
176	  net_debt_views: {release: View | null; contractual: View | null; releaseReported: {value: string; differenceToRelease: string | null; anchor: Anchor} | null};
177	  /** Two denominators, both named: before contra lines (the ledger's own base) and the reported gross debt of the note (the answer key's 13,1% and 19,4%); contractual-only inclusions never enter the second. */
178	  by_indexer: Array<{indexer: string; balance: string; shareOfGrossBeforeContra: string; shareOfReportedGrossDebt: string; rows: string[]}>;
179	  by_currency: Array<{currency: string; balance: string; shareOfGrossBeforeContra: string; shareOfReportedGrossDebt: string; rows: string[]}>;
180	  uncovered_terms: Array<{rowId: string; field: UncoveredField; state: "insufficient_evidence"; reason: string}>;
181	  trace: {calculations: Array<{id: string; formula: string; operands: Record<string, string>; result: string; unit: string}>; inputFingerprint: string; outputFingerprint: string};
182	};
183	
184	const d = (value: Decimal.Value) => new Decimal(value);
185	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
186	const share = (part: Decimal, whole: Decimal) => (whole.isZero() ? "0" : out(part.div(whole)));
187	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
188	const indexerOf = (row: Row): string => row.remuneration === null ? "unknown" : row.remuneration.type === "fixed" ? "fixed" : row.remuneration.index;
189	const DERIVATIVES = /derivativ|derivative/;
190	const CASH = /caixa|disponibilidade|cash/;
191	const RESIDUAL = /outra rubrica que se refira a divida onerosa|outra divida onerosa|outras dividas onerosas|other onerous debt|divida onerosa/;
192	
193	const DEBT = /emprestim|financiament|debenture|divida bruta|gross debt|loan|borrowing/;
194	const DEBT_BASE_OK = /divida bruta|gross debt|(?=[^.;]*emprestim)(?=[^.;]*financiament)(?=[^.;]*debenture)/;
195	/** Components that never belong to a net debt definition; their presence on the added side is a contradiction, not a nuance. */
196	const FOREIGN = /fornecedor|supplier|payable|estoque|inventor|receb|receivable|imobilizado|fixed asset|salario|tributo|tax/;
197	const normalize = (text: string) => text.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
198	
199	/** What a definition adds and what it deducts: the text before the first "menos"/"less"/"minus" and the text after it. */
200	export function parseDefinition(text: string): {added: string; deducted: string | null} {
201	  const plain = normalize(text);
202	  // "(-)" is how a release table writes a deduction; the word forms cover indentures and prose.
203	  const match = /\(\s*[-\u2212]\s*\)|\b(menos|less|minus|deduzid[oa]s?( de)?)\b/.exec(plain);
204	  if (!match) return {added: plain, deducted: null};
205	  return {added: plain.slice(0, match.index), deducted: plain.slice(match.index + match[0].length)};
206	}
207	
208	const INVESTMENTS = /aplicac|investment/;
209	const DERIVATIVE_LIABILITIES = /derivativ[^.;]{0,40}passiv|passiv[^.;]{0,40}derivativ|derivative liabilit/;
210	const DERIVATIVE_ASSETS = /derivativ[^.;]{0,40}ativ(?!o? ?e)|ativ[^.;]{0,40}derivativ|derivative asset/;
211	
212	/**
213	 * The text of a definition must agree, operand by operand and side by side, with the formula the view
214	 * executes; a contradiction is a block, not a warning. The release view is debt less cash and investments;
215	 * the contractual view adds derivative liabilities and deducts derivative assets as well.
216	 */
217	function definitionDisagreement(name: "release" | "contractual", text: string): string | null {
218	  const parsed = parseDefinition(text);
219	  if (parsed.deducted === null) return `the ${name} definition never deducts anything; the view deducts cash and investments`;
220	  if (!DEBT.test(parsed.added)) return `the ${name} definition adds no debt line; the view sums loans, financings and debentures`;
221	  if (!DEBT_BASE_OK.test(parsed.added)) return `the ${name} definition does not add the whole debt base (loans, financings and debentures, or gross debt); the view sums all three`;
222	  if (FOREIGN.test(parsed.added) || FOREIGN.test(parsed.deducted)) return `the ${name} definition names a component that is not debt nor cash (${(FOREIGN.exec(parsed.added) ?? FOREIGN.exec(parsed.deducted))![0]}); the view has no such operand`;
223	  const deductedDebt = /emprestim|financiament|debenture|subordinad|divida bruta|gross debt|loan|borrowing/.exec(parsed.deducted.replace(/divida liquida|net debt/g, ""));
224	  if (deductedDebt) return `the ${name} definition deducts a debt operand (${deductedDebt[0]}); the view deducts only cash, investments and derivative assets`;
225	  if (!CASH.test(parsed.deducted)) return `the ${name} definition does not deduct cash; the view deducts cash and equivalents`;
226	  if (!INVESTMENTS.test(parsed.deducted)) return `the ${name} definition does not deduct financial investments; the view deducts them`;
227	  if (CASH.test(parsed.added) || INVESTMENTS.test(parsed.added)) return `the ${name} definition adds cash or investments; the view deducts them`;
228	  if (name === "release") {
229	    if (DERIVATIVES.test(plainText(text))) return "the release definition mentions derivatives; the release view executed excludes them";
230	    return null;
231	  }
232	  if (!DERIVATIVE_LIABILITIES.test(parsed.added)) return "the contractual definition does not add derivative liabilities; the contractual view executed adds them";
233	  if (!DERIVATIVE_ASSETS.test(parsed.deducted)) return "the contractual definition does not deduct derivative assets; the contractual view executed deducts them";
234	  if (DERIVATIVE_ASSETS.test(parsed.added)) return "the contractual definition adds derivative assets; the view deducts them";
235	  if (DERIVATIVE_LIABILITIES.test(parsed.deducted)) return "the contractual definition deducts derivative liabilities; the view adds them";
236	  return null;
237	}
238	const plainText = (text: string) => normalize(text);
239	
240	function canonical(input: z.infer<typeof debtLedgerInputSchema>) {
241	  return {
242	    ...input,
243	    rows: [...input.rows].sort((a, b) => compare(a.id, b.id)).map((row) => (row.obligation ? {...row, obligation: {...row.obligation, views: [...row.obligation.views].sort(compare)}} : row)),
244	    schedule: input.schedule ? {...input.schedule, periods: [...input.schedule.periods].sort((a, b) => compare(a.period, b.period))} : undefined,
245	  };
246	}
247	
248	/** JSON with object keys sorted at every level, so the fingerprint ignores the order a caller wrote its keys in. */
249	export const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
250	
251	export function buildDebtLedger(raw: DebtLedgerInput): DebtLedgerOutput {
252	  const input = canonical(debtLedgerInputSchema.parse(raw));
253	  const calculations: DebtLedgerOutput["trace"]["calculations"] = [];
254	  const record = (calculation: Omit<DebtLedgerOutput["trace"]["calculations"][number], "unit">) => calculations.push({...calculation, unit: input.unit});
255	  const rows = input.source === "release_only" ? [] : input.rows;
256	  const blockReasons: string[] = [];
257	  const incompleteReasons: string[] = [];
258	  const tolerance = d(input.tolerance.value);
259	  const toleranceOut = {value: input.tolerance.value, policyKey: input.tolerance.policyKey ?? null, policyVersion: input.tolerance.policyVersion ?? null};
260	
261	  const balances = Object.fromEntries(rows.map((row) => [row.id, row.balance]));
262	  const gross = rows.reduce((sum, row) => sum.plus(row.balance), d(0));
263	  // What the statements report as debt: the release view plus the contra lines; a row only an indenture includes stays out of the identity with the balance sheet.
264	  const reportedRows = rows.filter((row) => row.contra || row.obligation!.views.includes("release"));
265	  const contractualOnly = rows.filter((row) => !row.contra && !row.obligation!.views.includes("release"));
266	  const grossReported = reportedRows.reduce((sum, row) => sum.plus(row.balance), d(0));
267	  const grossBeforeContra = rows.filter((row) => !row.contra).reduce((sum, row) => sum.plus(row.balance), d(0));
268	  const priorKnown = rows.length > 0 && rows.every((row) => row.priorBalance !== null);
269	  const grossPrior = priorKnown ? rows.reduce((sum, row) => sum.plus(row.priorBalance!), d(0)) : null;
270	  record({id: "financial.debt_ledger_balance", formula: "sum(rows.balance)", operands: balances, result: out(gross)});
271	  record({id: "financial.debt_ledger_balance_reported", formula: "sum(rows.balance where row in release view or contra)", operands: Object.fromEntries(reportedRows.map((row) => [row.id, row.balance])), result: out(grossReported)});
272	  record({id: "financial.debt_ledger_balance_before_contra", formula: "sum(rows.balance where not contra)", operands: Object.fromEntries(rows.filter((row) => !row.contra).map((row) => [row.id, row.balance])), result: out(grossBeforeContra)});
273	  if (grossPrior) record({id: "financial.debt_ledger_balance_prior", formula: "sum(rows.priorBalance)", operands: Object.fromEntries(rows.map((row) => [row.id, row.priorBalance!])), result: out(grossPrior)});
274	
275	  if (input.source === "release_only") blockReasons.push("only a release is in the base; a ledger needs the debt note of the financial statements, so no row is produced");
276	  if (input.source === "note" && rows.length === 0 && !input.noDebtEvidence) blockReasons.push("no rows and no evidence that the company has no onerous debt: silence is not an empty ledger");
277	  if (input.source === "note" && rows.length === 0 && input.noDebtEvidence && !input.balanceSheet) blockReasons.push("the base claims no onerous debt but no balance sheet proves a zero balance; an empty ledger needs the balance sheet");
278	  if (input.noDebtEvidence && rows.length > 0) blockReasons.push("the base claims no onerous debt and the note carries rows; the contradiction blocks the ledger");
279	  if (rows.length === 0 && input.noDebtEvidence && input.balanceSheet && !d(input.balanceSheet.current).plus(input.balanceSheet.nonCurrent).isZero()) {
280	    blockReasons.push("the base claims no onerous debt but the balance sheet carries debt totals; the contradiction blocks the ledger");
281	  }
282	
283	  let reconciliation: DebtLedgerOutput["reconciliation"] = {total: {state: "not_possible", balanceSheetTotal: null, difference: null}, split: {state: "not_possible", currentDifference: null, nonCurrentDifference: null, reason: "no balance sheet in the base"}, tolerance: toleranceOut, anchor: null};
284	  if (input.balanceSheet && rows.length > 0) {
285	    const sheetCurrent = d(input.balanceSheet.current);
286	    const sheetNonCurrent = d(input.balanceSheet.nonCurrent);
287	    const total = sheetCurrent.plus(sheetNonCurrent);
288	    const difference = grossReported.minus(total);
289	    const within = difference.abs().lte(tolerance);
290	    record({id: "financial.accounting_identity", formula: "sum(reported rows.balance) - (balanceSheet.current + balanceSheet.nonCurrent)", operands: {ledgerReported: out(grossReported), contractualOnly: out(gross.minus(grossReported)), balanceSheetCurrent: out(sheetCurrent), balanceSheetNonCurrent: out(sheetNonCurrent), tolerance: input.tolerance.value}, result: out(difference)});
291	    if (!within) blockReasons.push(`reported ledger total ${out(grossReported)} differs from the balance sheet ${out(total)} by ${out(difference)}, above the tolerance ${input.tolerance.value}`);
