217	function definitionDisagreement(name: "release" | "contractual", text: string): string | null {
218	  const parsed = parseDefinition(text);
219	  if (parsed.deducted === null) return `the ${name} definition never deducts anything; the view deducts cash and investments`;
220	  if (!DEBT.test(parsed.added)) return `the ${name} definition adds no debt line; the view sums loans, financings and debentures`;
221	  if (!DEBT_BASE_OK.test(parsed.added)) return `the ${name} definition does not add the whole debt base (loans, financings and debentures, or gross debt); the view sums all three`;
222	  if (FOREIGN.test(parsed.added) || FOREIGN.test(parsed.deducted)) return `the ${name} definition names a component that is not debt nor cash (${(FOREIGN.exec(parsed.added) ?? FOREIGN.exec(parsed.deducted))![0]}); the view has no such operand`;
