254	  const record = (calculation: Omit<DebtLedgerOutput["trace"]["calculations"][number], "unit">) => calculations.push({...calculation, unit: input.unit});
255	  const rows = input.source === "release_only" ? [] : input.rows;
256	  const blockReasons: string[] = [];
257	  const incompleteReasons: string[] = [];
