261	  const balances = Object.fromEntries(rows.map((row) => [row.id, row.balance]));
262	  const gross = rows.reduce((sum, row) => sum.plus(row.balance), d(0));
263	  // What the statements report as debt: the release view plus the contra lines; a row only an indenture includes stays out of the identity with the balance sheet.
264	  const reportedRows = rows.filter((row) => row.contra || row.obligation!.views.includes("release"));
265	  const contractualOnly = rows.filter((row) => !row.contra && !row.obligation!.views.includes("release"));
266	  const grossReported = reportedRows.reduce((sum, row) => sum.plus(row.balance), d(0));
267	  const grossBeforeContra = rows.filter((row) => !row.contra).reduce((sum, row) => sum.plus(row.balance), d(0));
